def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    colors = set(counts) - {bg}
    for color in colors:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr,dc in ((1,1),(1,-1)):
            groups = {}
            for r,c in pts:
                groups.setdefault(r-c if dr == dc else r+c, []).append((r,c))
            for group in groups.values():
                if len(group) < 2: continue
                group.sort(key=lambda p: p[0])
                group_set = set(group)
                for endpoint, step in ((group[0],(-dr,-dc)), (group[-1],(dr,dc))):
                    er,ec=endpoint
                    # A same-color branch at the endpoint anchors this end of the line.
                    branched = any((er+rr,ec+cc) in pts and (er+rr,ec+cc) not in group_set
                                   for rr in (-1,0,1) for cc in (-1,0,1) if rr or cc)
                    if branched: continue
                    r,c=er+step[0],ec+step[1]
                    while 0<=r<h and 0<=c<w and out[r][c]==bg:
                        out[r][c]=color
                        r+=step[0]; c+=step[1]
    return out

